INSERT INTO pendaftar (pendaftar_id, user_id, nim, nama, nama_panggilan, jenis_kelamin, ttl, alamat_asal, alamat_sekarang, no_hp, hobby, cita_cita, motto_hidup, semester, prodi, ipk, bidang_pilihan_1, bidang_pilihan_2, keterampilan, motivasi, target_iela, riwayat_organisasi, pelatihan_diikuti, buku_diresume, url_foto, url_khs, url_cv, url_sertifikat, url_resume, status_pendaftaran, qr_code_id, url_jurnal_referensi) VALUES ('PDF-5661', 'USR-3538', '1411250002', 'Aditya Ilham Wijanarko Putra', 'Adit', 'Laki-laki', 'Tuban, 02 Agu 2005', 'RT 05/RW 01, Dsn Panjen, Ds Jenggolo, Kec Jenu, Kab Tuban', 'RT 05/RW 01, Dsn Panjen, Ds Jenggolo, Kec Jenu, Kab Tuban', '88989999344.0', 'Olahraga', 'Engineer', 'Ambil resiko atau kehilangan kesempatan', '3.0', 'Teknik Industri Unirow', 3.43, '4. Manufaktur (a. Bubut)', '4. Manufaktur (b. 3D Printing)', 'Bubut dan Frais', 'Ingin memperdalam praktik pemesinan, khusunya di mesin bubut dan melatih kemampuan menjelaskan materi kepada orang lain. Saya juga siap membantu praktikan dan serta menjaga keselamatan kerja', 'Menjaga K3 di setiap proses manufaktur, terbiasa maintenance mesin sehingga tahu problem solving pada mesin ketika mesin eror,  menguasai mesin serta alat ukur, dan mampu menjelaskan kepada praktikan tentang mesin atau komponen yang ada di lab secara jelas', 'Ikatan Pencak Silat Nahdhotul Ulama'' Pagar Nusa', 'Tes Akhir Bubut Di SMK Yang di Adakan Oleh BLKI Tuban', 'Pengaruh Kecepatan Putaran Spindle dan Feed Rate terhadap Tingkat Kekasaran Permukaan Material AISI 4140 pada Proses Bubut', 'https://drive.google.com/file/d/1wXzL7NcZglInm8eBkKgSwr6tVZLgrP7v/view?usp=drivesdk', 'https://drive.google.com/file/d/144ytvH2zcN8uekkYUySEFLu_wSty7ZvQ/view?usp=drivesdk', 'https://drive.google.com/file/d/1r_HWWmO335eHFP_oV9luCUbpRhPRuLTx/view?usp=drivesdk', 'https://drive.google.com/file/d/1vKEclg8gzXT_BNAzvrtgJZPaCVF8jAAy/view?usp=drivesdk', 'https://drive.google.com/file/d/1BSeZEY6iLmcMbMdaGsKOyReqoSScW3Vm/view?usp=drivesdk', 'Lolos Asisten Lab 2027', 'QR-IELA-1411250002', 'https://drive.google.com/file/d/1j7aycUu-Du5XgajIxZsrRB87tykmTMNb/view?usp=drivesdk') ON CONFLICT (pendaftar_id) DO NOTHING;
INSERT INTO pendaftar (pendaftar_id, user_id, nim, nama, nama_panggilan, jenis_kelamin, ttl, alamat_asal, alamat_sekarang, no_hp, hobby, cita_cita, motto_hidup, semester, prodi, ipk, bidang_pilihan_1, bidang_pilihan_2, keterampilan, motivasi, target_iela, riwayat_organisasi, pelatihan_diikuti, buku_diresume, url_foto, url_khs, url_cv, url_sertifikat, url_resume, status_pendaftaran, qr_code_id, url_jurnal_referensi) VALUES ('PDF-6930', 'USR-3665', '1411250024', 'Hidayatul umam al anshori', 'Hidayatul', 'Laki-laki', 'Tuban, 11 juli 2007', 'Ds. Merkawang, Kec. Tambakboyo, Kab. Tuban', 'Ds.Temandang, Kec. Merakurak, Kab. Tuban', '+62 859-3444-7983', 'Ngopi', 'Arsitek', 'BERBUAT BAIKLAH SEAKAN BESOK KAU AKAN MATI', '3.0', 'Teknik Industri Unirow', 3.44, '4. Manufaktur (a. Bubut)', '4. Manufaktur (c. CNC)', 'Mampu mengoperasikan software Inventor', 'Ingin mengembangkan pemahaman mendalam di bidang Manufaktur, mengasah keterampilan teknis seperti software Inventor dan pengoperasian mesin bubut, serta berkontribusi aktif dalam kegiatan praktikum dan riset di Lab Teknik Industri UNIROW', 'Menguasai pengoperasian serta perawatan alat laboratorium (khususnya mesin manufaktur), meningkatkan soft skills dalam kepemimpinan dan komunikasi, serta membantu kelancaran praktikum mahasiswa.', 'Dewan Ambalan SMKN Tambakboyo', 'operator CNC Gas Cuting di PT. Bahtera Cipta Anugrah', 'OPTIMASI PARAMETER PEMOTONGAN MESIN BUBUT CNC  TERHADAP KEKASARAN PERMUKAAN DENGAN RESPONSE  SURFACE METHODOLOGY (RSM) PADA MATERIAL Al-6061', 'https://drive.google.com/file/d/1gpnrFPy1k7tHggzfARxrVFgJ9cuIwhpt/view?usp=drivesdk', 'https://drive.google.com/file/d/1C4Cu9gnUy82TEx-hXE6SSR7lMmyu60-i/view?usp=drivesdk', 'https://drive.google.com/file/d/1fdPeheAJn5D0yLmkfkNOgGrUeQ6d6S_F/view?usp=drivesdk', 'https://drive.google.com/file/d/1UCXubMR5y1-IxwBMeQdVSkN4xU-mo3oA/view?usp=drivesdk', 'https://drive.google.com/file/d/1_HaMIqw0UUk1KXmEv90KONDN3ltDXHhN/view?usp=drivesdk', 'Tidak Lolos', 'QR-IELA-1411260024', 'https://drive.google.com/file/d/1KSpUG25A9nhCjpeRwdIvut1OCbe7BgJ2/view?usp=drivesdk') ON CONFLICT (pendaftar_id) DO NOTHING;
