INSERT INTO pendaftar (pendaftar_id, user_id, nim, nama, nama_panggilan, jenis_kelamin, ttl, alamat_asal, alamat_sekarang, no_hp, hobby, cita_cita, motto_hidup, semester, prodi, ipk, bidang_pilihan_1, bidang_pilihan_2, keterampilan, motivasi, target_iela, riwayat_organisasi, pelatihan_diikuti, buku_diresume, url_foto, url_khs, url_cv, url_sertifikat, url_resume, status_pendaftaran, qr_code_id, url_jurnal_referensi) VALUES ('PDF-8632', 'USR-7228', '1411250046', 'RAIKHA ZINATUL ASRIYAH', 'RAIKHA', 'Perempuan', 'Tuban, 16 Desember 2006', 'Desa. Margomulyo, Kec.Kerek Kab.Tuban Jawa Timur', 'Desa. Margomulyo, Kec.Kerek Kab.Tuban Jawa Timur', '895396333732.0', 'Olahraga dan travelling', 'Entrepreneur', 'Jangan samakan 1 menitmu dengan 1 menit orang lain.', '3.0', 'Teknik Industri Unirow', 3.75, '5. Algoritma', '4. Manufaktur (c. CNC)', 'Python, UGS, Aspire', 'Motivasi saya mendaftar asisten laboratorium bidang logaritma & pemrograman karena mata kuliah ini adalah salah satu yang paling saya kuasai, dari pengalaman saya selama SMK pada jurusan Rekayasa Perangkat Lunak (RPL) yang mempelejari tentang pemrograman. Juga saya ingin membantu teman-teman yang masih kesulitan mengenai logaritma & pemrograman serta memperdalam pemahaman saya sendiri karena butuh penguasaan yang lebih kuat.', 'Target saya selama di IELA adalah menguasai materi lebih dalam, membantu praktikan memahami materi, menjalankan tugas sebagai asisten laboratorium dengan baik, serta mengembangkan kemampuan diri saya.', 'Dewan Ambalan', 'Pelatihan Excel', 'Meningkatkan Logika Pemrograman Siswa SMK Melalui Pelatihan Pengenalan Flowchart dan Pseudocode', 'https://drive.google.com/file/d/167I2c3p2vwJrYO5EuPE3wBStz_dL2l5q/view?usp=drivesdk', 'https://drive.google.com/file/d/1j1MRzxZdFWR5OSeFJ8Nb9IQ1dkWmTBxG/view?usp=drivesdk', 'https://drive.google.com/file/d/16iuBecAhjCf9YOR3b9pRFjzwGS2GWC4i/view?usp=drivesdk', 'https://drive.google.com/file/d/1rdJRlCAb_sNvItZO7G2BWRraeYWzONVl/view?usp=drivesdk', 'https://drive.google.com/file/d/1HjvE59d9pBbi3wirHalMwvbmt_XZvWg4/view?usp=drivesdk', 'Lolos Asisten Lab 2027', 'QR-IELA-1411250052', 'https://drive.google.com/file/d/1uedoro4Sb0xBUJohq6DUT1TRb8vW3Vbx/view?usp=drivesdk') ON CONFLICT (pendaftar_id) DO NOTHING;
INSERT INTO pendaftar (pendaftar_id, user_id, nim, nama, nama_panggilan, jenis_kelamin, ttl, alamat_asal, alamat_sekarang, no_hp, hobby, cita_cita, motto_hidup, semester, prodi, ipk, bidang_pilihan_1, bidang_pilihan_2, keterampilan, motivasi, target_iela, riwayat_organisasi, pelatihan_diikuti, buku_diresume, url_foto, url_khs, url_cv, url_sertifikat, url_resume, status_pendaftaran, qr_code_id, url_jurnal_referensi) VALUES ('PDF-2459', 'USR-4887', '1411250047', 'Reihaniza Abimanyu Pambudi', 'Reihaniza', 'Laki-laki', 'Tuban, 17 Desember 2006', 'Desa Rawasan RT01/RW03 Kecamatan Jenu, Kabupaten Tuban', 'Desa Rawasan RT01/RW03 Kecamatan Jenu, Kabupaten Tuban', '85649776243.0', 'Futsal', 'pegawai BUMN', 'Gagal mencoba lebih baik dari pada tidak mencoba', '3.0', 'Teknik Industri Unirow', 3.39, '4. Manufaktur (a. Bubut)', '4. Manufaktur (b. 3D Printing)', 'Bubut, Frais', 'Motivasi saya mendaftar sebagai asisten laboratorium bubut adalah untuk menambah ilmu dan keterampilan pemesinan, memperoleh pengalaman, serta melatih kedisiplinan, tanggung jawab, dan kemampuan membimbing praktikan.', 'ingin menjadi asisten yang kompeten, disiplin, dan bertanggung jawab serta mampu membantu praktikan memahami proses pembubutan dengan baik.', 'PR IPPNU', '-', 'Pengaruh Variasi Kedalaman Potong dan Kecepatan Putar Mesin Bubut Terhadap Kekasaran Permukaan Benda Kerja Hasil Pembubutan Rata Pada Bahan Baja ST 37.', 'https://drive.google.com/file/d/12jvc26vRndS16kM6f5qg9XLhqNNE1aN-/view?usp=drivesdk', 'https://drive.google.com/file/d/12CC4GcwxC7KGHrcBN1G2mWPyzIP4hrsL/view?usp=drivesdk', 'https://drive.google.com/file/d/1RO-C8pJ3DHdVDnsxl8co-KLtFKm1x4VM/view?usp=drivesdk', '#', 'https://drive.google.com/file/d/1EgCmH1dcjvwIg3tGcwhFd6gi48yuE1lQ/view?usp=drivesdk', 'Tidak Lolos', 'QR-IELA-1411250047', 'https://drive.google.com/file/d/1-dJ1JVkgHYkZUiaJiT5iFu0LSocVSIHX/view?usp=drivesdk') ON CONFLICT (pendaftar_id) DO NOTHING;
INSERT INTO pendaftar (pendaftar_id, user_id, nim, nama, nama_panggilan, jenis_kelamin, ttl, alamat_asal, alamat_sekarang, no_hp, hobby, cita_cita, motto_hidup, semester, prodi, ipk, bidang_pilihan_1, bidang_pilihan_2, keterampilan, motivasi, target_iela, riwayat_organisasi, pelatihan_diikuti, buku_diresume, url_foto, url_khs, url_cv, url_sertifikat, url_resume, status_pendaftaran, qr_code_id, url_jurnal_referensi) VALUES ('PDF-3055', 'USR-6815', '1411250014', 'Denis Fitria Echa Oxtavia', 'Echa', 'Perempuan', 'Tuban, 13 oktober 2007', 'ds temaji ,kecamatan jenu ,kabupaten tuban', 'ds temaji ,kecamatan jenu ,kabupaten tuban', '81333125794.0', 'menulis dan membaca', 'Menjadi seorang profesional di bidang Teknik Industri yang kompeten, disiplin, dan mampu memberikan kontribusi dalam meningkatkan efisiensi serta kualitas kerja di suatu perusahaan.', 'Tidak harus sempurna untuk memulai, tetapi harus mau belajar untuk berkembang.', '3.0', 'Teknik Industri Unirow', 3.80, '1. Fisika', '1. Fisika', 'Microsoft Excel, Microsoft Word, pengolahan data, dasar-dasar fisika, serta pemahaman dasar keselamatan dan kesehatan kerja (K3).', 'Saya ingin menjadi asisten laboratorium untuk menambah pengalaman, memperdalam pemahaman materi praktikum, serta mengembangkan kemampuan komunikasi, kedisiplinan, dan tanggung jawab. Saya juga ingin membantu mahasiswa lain agar dapat memahami praktikum dengan baik.', 'Meningkatkan kemampuan teknis dan pemahaman materi praktikum, memperoleh pengalaman sebagai asisten laboratorium, serta berkontribusi dalam menjaga ketertiban dan kelancaran kegiatan praktikum.', 'Belum memiliki pengalaman organisasi.', 'Pelatihan Microsoft Excel, TOEFL, dan Persiapan Karier, jika memang sudah pernah mengikuti atau memiliki sertifikat tersebut.', 'Analisis Nilai Konstanta Pegas Berdasarkan Nilai Gravitasi Bumi dan Bulan Menggunakan VLab Amrita', 'https://drive.google.com/file/d/15XSLbDfTjJhPqx2d5ip6bkvAgTTD4C2r/view?usp=drivesdk', 'https://drive.google.com/file/d/1Dy3SmSwmRtqYM9TZIremf8iE-UzuYE7N/view?usp=drivesdk', 'https://drive.google.com/file/d/1rEAfbL9197VpZESWhwC0b2_xz8BeAuWW/view?usp=drivesdk', 'https://drive.google.com/file/d/1DK_TJxQH1k7cwRcOQ58BDeHMhbfqMO1Q/view?usp=drivesdk', 'https://drive.google.com/file/d/1jdztFaaAQe-vXHkyzTt2U5NXNddvFsc5/view?usp=drivesdk', 'Lolos Asisten Lab 2027', 'QR-IELA-1411250014', 'https://drive.google.com/file/d/1sHa4WzWQyESDcPCiSXTtcVTKj4TyMt58/view?usp=drivesdk') ON CONFLICT (pendaftar_id) DO NOTHING;
INSERT INTO pendaftar (pendaftar_id, user_id, nim, nama, nama_panggilan, jenis_kelamin, ttl, alamat_asal, alamat_sekarang, no_hp, hobby, cita_cita, motto_hidup, semester, prodi, ipk, bidang_pilihan_1, bidang_pilihan_2, keterampilan, motivasi, target_iela, riwayat_organisasi, pelatihan_diikuti, buku_diresume, url_foto, url_khs, url_cv, url_sertifikat, url_resume, status_pendaftaran, qr_code_id, url_jurnal_referensi) VALUES ('PDF-7389', 'USR-8788', '1411250021', 'Ella Nova Setya Ningrum', 'Ella', 'Perempuan', 'Tuban, 17 November 2006', 'Ds Tasikharjo Kec Jenu Kab Tuban', 'Ds Tasikharjo Kec Jenu Kab Tuban', '89652583752.0', 'belajar hal baru', 'Menjadi lulusan yang kompeten, profesional di bidang Teknik Industri, memiliki karir yang baik dan terus mengembangkan kemampuan diri', 'Belajar dengan rasa ingin tahu, bekerja dengan ketelitian, dan mengabdi dengan tanggung jawab', '3.0', 'Teknik Industri Unirow', 3.85, '1. Fisika', '1. Fisika', 'Mampu mengoperasikan Microsoft Word dan Excel untuk pengolahan data dasar, menyusun laporan praktikum, serta melakukan perhitungan menggunakan rumus dasar Excel. Memiliki kemauan untuk mempelajari penggunaan alat laboratorium, pengolahan data, dan penerapan ilmu Teknik Industri.', 'Saya ingin menjadi asisten laboratorium untuk memperdalam pemahaman konsep Fisika melalui kegiatan praktikum, meningkatkan keterampilan dalam melakukan pengukuran dan pengolahan data, serta memperoleh pengalaman dalam membantu pelaksanaan praktikum. Saya juga ingin melatih kedisiplinan, ketelitian, tanggung jawab, dan kemampuan bekerja sama.', 'Target saya adalah memperdalam pemahaman teori dan penerapan Fisika, meningkatkan kemampuan dalam melakukan eksperimen serta menganalisis hasil pengukuran, dan memahami penggunaan alat-alat laboratorium. Saya juga ingin mengembangkan kemampuan komunikasi dan kerja sama agar dapat menjadi asisten yang kompeten, disiplin, dan bertanggung jawab.', 'Belum memiliki pengalaman organisasi formal, tetapi memiliki kemauan untuk belajar, bekerja sama dalam tim, dan berpartisipasi aktif dalam kegiatan akademik.', 'Pelatihan Microsoft Excel – meningkatkan keterampilan dalam penggunaan Microsoft Excel untuk pengolahan data. Pelatihan Pengembangan Karier dan Persiapan Karier – menambah pemahaman mengenai pengembangan potensi diri dan persiapan memasuki dunia kerja.', 'Verifying Hooke''s Law in Undergraduate Physics Laboratory: An Experimental Study with Emphasis on Measurement Uncertainty Awareness (Sihite dkk., JPIF Universitas Garut).', 'https://drive.google.com/file/d/15gb3Vqj1xdVYM-O-kitVR9eDGHMjH4lv/view?usp=drivesdk', 'https://drive.google.com/file/d/1eTuX7hCSi1fWOP0-j_8qByFPWfbLgKQ2/view?usp=drivesdk', 'https://drive.google.com/file/d/1EmDSdgoPBFE7pFnnAOaNruV5UDbAPXpZ/view?usp=drivesdk', 'https://drive.google.com/file/d/11qcRDqZ13oQBxe_KrwMYHfpb_u9eOPBM/view?usp=drivesdk', 'https://drive.google.com/file/d/185i7R2Fc8mv2zQpI3ulqiCBiYy4OnA46/view?usp=drivesdk', 'Tidak Lolos', 'QR-IELA-1411250021', 'https://drive.google.com/file/d/1PWWXsQt_yDx8KQiVNfL29gOsfaCHKHdL/view?usp=drivesdk') ON CONFLICT (pendaftar_id) DO NOTHING;
INSERT INTO pendaftar (pendaftar_id, user_id, nim, nama, nama_panggilan, jenis_kelamin, ttl, alamat_asal, alamat_sekarang, no_hp, hobby, cita_cita, motto_hidup, semester, prodi, ipk, bidang_pilihan_1, bidang_pilihan_2, keterampilan, motivasi, target_iela, riwayat_organisasi, pelatihan_diikuti, buku_diresume, url_foto, url_khs, url_cv, url_sertifikat, url_resume, status_pendaftaran, qr_code_id, url_jurnal_referensi) VALUES ('PDF-7614', 'USR-6188', '1411250022', 'Elly Novi Setya Ningrum', 'Elly', 'Perempuan', 'Tuban, 17 November 2006', 'Ds Tasikharjo kec. Jenu Kab. Tuban', 'Ds Tasikharjo Kec. Jenu Kab. Tuban', '0882-0090-02405', 'mempelajari hal baru', 'Menjadi profesional dibidang Teknik Industri yang kompeten,  memiliki karis yang baik, sukses dan juga terus bisa mengembangkan kemampuan  diri', 'Terus Belajar, Berani Mencoba dan Bertanggung Jawab Atas Setiap Proses', '3.0', 'Teknik Industri Unirow', 3.84, '2. Ergonomi', '2. Ergonomi', 'Mampu mengoperasikan Microsoft Word dan Excel, teliti dalam mengolah data, serta memiliki kemauan untuk mempelajari hal baru.', 'Ingin menambah pengalaman, memperdalam pemahaman materi perkuliahan, serta belajar bertanggung jawab dan bekerja sama dalam lingkungan laboratorium.', 'Memperdalam pemahaman tentang ergonomi, meningkatkan keterampilan dalam praktikum dan analisis data, serta menjadi asisten yang disiplin dan bertanggung jawab, mengembangkan komunikasi.', 'Belum memiliki pengalaman organisasi formal,tapi saya memiliki kemauan untuk belajar dan bekerja sama dalam tim dan berpartisipasi dalam bidang akademik', 'Pelatihan Microsoft Excel dan Pengembangan Karier untuk meningkatkan keterampilan pengolahan data serta mempersiapkan diri menghadapi dunia kerja.', 'Analisis Postur Kerja Rula dan Reba', 'https://drive.google.com/file/d/1Io5fcbPz9f_DZ23aWCbmx64XIiTRLOC1/view?usp=drivesdk', 'https://drive.google.com/file/d/1DoPDIZxqhSKdVNj07akxbSXapV65eXJY/view?usp=drivesdk', 'https://drive.google.com/file/d/1QVu4MKOG-tAv2tMgycJVt1cIgzyLH2NQ/view?usp=drivesdk', 'https://drive.google.com/file/d/1u7RHVMUCgxKGfoFoVuM1Z5jnx56flQr0/view?usp=drivesdk', 'https://drive.google.com/file/d/1PNUp51UvEVYlHuZbdA4UKpVj6dLUM05k/view?usp=drivesdk', 'Lolos Asisten Lab 2027', 'QR-IELA-1411250022', 'https://drive.google.com/file/d/1ScjWKf7rFW4BDxu8oT5uolrKRx_dnFgs/view?usp=drivesdk') ON CONFLICT (pendaftar_id) DO NOTHING;
