INSERT INTO pendaftar (pendaftar_id, user_id, nim, nama, nama_panggilan, jenis_kelamin, ttl, alamat_asal, alamat_sekarang, no_hp, hobby, cita_cita, motto_hidup, semester, prodi, ipk, bidang_pilihan_1, bidang_pilihan_2, keterampilan, motivasi, target_iela, riwayat_organisasi, pelatihan_diikuti, buku_diresume, url_foto, url_khs, url_cv, url_sertifikat, url_resume, status_pendaftaran, qr_code_id, url_jurnal_referensi) VALUES ('PDF-4049', 'USR-3703', '1411250071', 'indria biru lutfi', 'indria', 'Perempuan', 'Tuban, 22 agustus 2005', 'jln. raya timur,jatirogo, Tuban, jawa timur', 'jalan manunggal, no. 90, kenduran, palang, tuban, jatim', '85807215023.0', 'memasak', 'offshore', 'sesuatu yang tidak dipertaruhkan, tidak akan dimenangkan', '3.0', 'Teknik Industri Unirow', 3.76, '3. Statistika', '3. Statistika', 'mampu penguasai beberapa software statistik seperti spss dan minitab, serta bisa kerja sama tim, menejemen waktu dan tanggung jawab', 'saya termotivasi mendaftar sebagai asisten laboratorium statistik karena saya ingin mendalami statiska melalui pengajaran dan pendampingan praktikum. bagi saya, menjadi aslab bukan hanya membantu mahasiswa, tetapi juga kesempatan untuk memperkuat pemahaman saya sendiri terhadap konsep dan aplikasi statistik', 'lulus seleksi dan mengikuti pelatihan aslab dengan baik, menguasai modul praktikum dan software statistik,menjadi aslab yang andal, disiplin, dsn di percaya', '-', '- pelatihan excel', 'pendampingan penggunaan  software SPSS dalam pengolahan data statistik', 'https://drive.google.com/file/d/1HT7TOdQc7504aIDEYuZ_X1gl5PUglVvq/view?usp=drivesdk', 'https://drive.google.com/file/d/1RDYLqjaRsQIt4_nqecBrSBoZMvnviFBB/view?usp=drivesdk', 'https://drive.google.com/file/d/1PZiclkbxlPKCE1UVx6RWJrmMy9CMGfGp/view?usp=drivesdk', 'https://drive.google.com/file/d/1nuQmA5Kr4z0r-9MkTtiPCsHsf8Dww1dX/view?usp=drivesdk', 'https://drive.google.com/file/d/1yB4X7El4xO5acPKsMVXilZIrvl0bXcaW/view?usp=drivesdk', 'Tidak Lolos', 'QR-IELA-1411250071', 'https: