INSERT INTO pendaftar (pendaftar_id, user_id, nim, nama, nama_panggilan, jenis_kelamin, ttl, alamat_asal, alamat_sekarang, no_hp, hobby, cita_cita, motto_hidup, semester, prodi, ipk, bidang_pilihan_1, bidang_pilihan_2, keterampilan, motivasi, target_iela, riwayat_organisasi, pelatihan_diikuti, buku_diresume, url_foto, url_khs, url_cv, url_sertifikat, url_resume, status_pendaftaran, qr_code_id, url_jurnal_referensi) VALUES ('PDF-1505', 'USR-9674', '1411250016', 'Dita Jinar Suryo A', 'Dita', 'Laki-laki', 'Tuban, 04 Juni 2006', 'Latsari GG sejahtera 1', 'Latsari GG sejahtera 1', '88803392360.0', 'Mancing', 'Karir yang bagus dalam bidang teknik industri', '"Menghubungkan teknologi dan memanusiakan sistem untuk menghasilkan hasil yang optimal.', '3.0', 'Teknik Industri Unirow', 3.21, '2. Ergonomi', '2. Ergonomi', 'Pemecahan  (Problem Solving) Masalah', 'Pengembangan Kompetensi Teknis (Hard Skills)', 'saya berkomitmen meningkatkan kompetensi teknis saya sekaligus membantu praktikan memahami esensi ilmu Teknik Industri', 'Walaupun saya belum mempunyai pengalaman organisasi yang formal saya akan berusaha dan tapi  saya akan memberikan yang terbaik, mau belajar dari pengalaman serta terus meningkatkan keterampilan dan kemampuan diri agar dapat menjadi asisten laboratorium yang bertanggung jawab', 'Secara formal saya belum pernah mengikuti workshop atau pelatihan berbayar di luar kampus. Namun, hal tersebut tidak membatasi saya untuk terus mengembangkan keterampilan.', 'INTEGRASI METODE RULA DAN NORDIC BODY MAP UNTUK EVALUASI RISIKO ERGONOMI PADA INDUSTRI TEMPE SKALA RUMAH TANGGA', 'https://drive.google.com/file/d/1610IEhSPgeaQnHwVI2dI9HDUJsHZ-xnB/view?usp=drivesdk', 'https://drive.google.com/file/d/1oeRrIprfylZglVUCKegyAXNWHyZWDao3/view?usp=drivesdk', 'https://drive.google.com/file/d/1QICdpk2v96Wzm7hMlE6J4Bt53ZBlO7nI/view?usp=drivesdk', 'https://drive.google.com/file/d/1MWoqH9jGN-0QUy8GYgVvi5c8xPgJxt18/view?usp=drivesdk', 'https://drive.google.com/file/d/1qUdlLOAvZFKtWSmfThp_G872Tcevgs9d/view?usp=drivesdk', 'Tidak Lolos', 'QR-IELA-1411250016', 'https://drive.google.com/file/d/1zmXkrC1mv82uWv5pgNKChu7LpWQhKFa3/view?usp=drivesdk') ON CONFLICT (pendaftar_id) DO NOTHING;
INSERT INTO pendaftar (pendaftar_id, user_id, nim, nama, nama_panggilan, jenis_kelamin, ttl, alamat_asal, alamat_sekarang, no_hp, hobby, cita_cita, motto_hidup, semester, prodi, ipk, bidang_pilihan_1, bidang_pilihan_2, keterampilan, motivasi, target_iela, riwayat_organisasi, pelatihan_diikuti, buku_diresume, url_foto, url_khs, url_cv, url_sertifikat, url_resume, status_pendaftaran, qr_code_id, url_jurnal_referensi) VALUES ('PDF-6349', 'USR-7791', '1411250030', 'Medika Graha Aditya', 'Medika', 'Laki-laki', 'Tuban, 17 April  2006', 'Dsn.Mahbeser Rt 003/ Rw 004 Ds.Tuwiri Kulon Kec.Merakurak Kab.Tuban', 'Dsn.Mahbeser Rt 003/ Rw 004 Ds.Tuwiri Kulon Kec.Merakurak Kab.Tuban', '81511440390.0', 'voli', 'Direktur Perusahaan Internasional', 'Jadikan setiap kesulitan sebagai pembelajaran dan setiap pencapaian sebagai alasan untuk terus berkembang.', '3.0', 'Teknik Industri Unirow', 3.79, '4. Manufaktur (c. CNC)', '3. Statistika', 'Aspire,Excel,Minitab,SPSS', 'Motivasi saya mendaftar sebagai Asisten Laboratorium CNC adalah untuk memperdalam pemahaman dan meningkatkan keterampilan dalam bidang pemesinan berbasis komputer, khususnya pengoperasian mesin CNC dan pemrograman G-code. Saya ingin mengembangkan kemampuan teknis, kedisiplinan, serta tanggung jawab melalui pengalaman menjadi asisten laboratorium. Selain itu, saya berharap dapat membantu mahasiswa lain dalam memahami materi praktikum dan menciptakan lingkungan pembelajaran yang efektif.', 'Menjadi asisten laboratorium yang kompeten, disiplin, dan bertanggung jawab, mampu memperdalam ilmu Teknik Industri, meningkatkan keterampilan analisis dan pemecahan masalah, serta berkontribusi dalam membantu praktikan memahami materi dan mengembangkan kualitas pembelajaran di laboratorium.', 'Karang Taruna', '-', 'Analisis Perancangan Mesin Cnc Drawing Pan Berbasis Arduino Untuk Penulisan Ijazah di Taman Kanak-Kanak Al Hikmah Sekarmojo', 'https://drive.google.com/file/d/1ECyshBMxPHa3c3d_7Nxb1Op5TCeYDlW2/view?usp=drivesdk', 'https://drive.google.com/file/d/1q17IPrTcN27goHZM4ZAKfPkfrUsI1hUU/view?usp=drivesdk', 'https://drive.google.com/file/d/1oAmsv92Ufmw2VkW0F3vYvlaNOChfXH-s/view?usp=drivesdk', 'https://drive.google.com/file/d/1xnsTl720TwINEXDMpT_v6WKcK1rr1qPW/view?usp=drivesdk', 'https://drive.google.com/file/d/11nNneGjDb1V0fim_TZzUqCHDgxkxKwTd/view?usp=drivesdk', 'Lolos Asisten Lab 2027', 'QR-IELA-1411250030', 'https://drive.google.com/file/d/1AfOhqcWFUKJsUvQhVxhpHChQ7gvn-kGb/view?usp=drivesdk') ON CONFLICT (pendaftar_id) DO NOTHING;
INSERT INTO pendaftar (pendaftar_id, user_id, nim, nama, nama_panggilan, jenis_kelamin, ttl, alamat_asal, alamat_sekarang, no_hp, hobby, cita_cita, motto_hidup, semester, prodi, ipk, bidang_pilihan_1, bidang_pilihan_2, keterampilan, motivasi, target_iela, riwayat_organisasi, pelatihan_diikuti, buku_diresume, url_foto, url_khs, url_cv, url_sertifikat, url_resume, status_pendaftaran, qr_code_id, url_jurnal_referensi) VALUES ('PDF-2978', 'USR-1761', '1411250026', 'Isma Nayla Munfa''atin', 'Isma', 'Perempuan', 'Tuban, 23 Januari 2007', 'Jenggolo, Jenu, Tuban', 'Jenggolo, Jenu, Tuban', '85648013314.0', 'Mendengar Musik', 'Psikolog', 'Let them, it will pass, time will tell', '3.0', 'Teknik Industri Unirow', 3.74, '5. Algoritma', '5. Algoritma', 'Menguasai Microsoft Word, basic algoritma pemrograman, dan basic excel', 'Saya tertarik menjadi asisten laboratorium karena ingin belajar lebih banyak, tidak hanya melalui teori di kelas, tetapi juga melalui praktik secara langsung. Saya ingin memperdalam pemahaman materi, melatih ketelitian dan kedisiplinan, serta belajar bertanggung jawab dalam menjalankan tugas.', 'Target saya adalah memperdalam ilmu, menambah pengalaman, serta mengembangkan kemampuan komunikasi dan kerja sama tim. Saya juga ingin menjadi asisten yang bertanggung jawab dan bisa membantu mahasiswa lain selama praktikum.', 'PR IPPNU Jenggolo', 'Pelatihan Excel', 'Pengaruh penerapan algoritma pemrograman dalam dunia pekerjaan (studi kasus metode deep learning)', 'https://drive.google.com/file/d/1vR1Xvj72WoOZE-iZWp62qWBOSAUl7nFU/view?usp=drivesdk', 'https://drive.google.com/file/d/1w-BuYN3pL9Y38Y5YU-ztEopejS7_-QHh/view?usp=drivesdk', 'https://drive.google.com/file/d/1TyGTUh-WKS02Kudzni7vLOqAMhEFesZt/view?usp=drivesdk', 'https://drive.google.com/file/d/1mn96cCTtGfJxUmtRXJLLuabXTOHRQHkK/view?usp=drivesdk', 'https://drive.google.com/file/d/1KC_sE6gMni0xpas53VByXB8I6IP1ES11/view?usp=drivesdk', 'Lolos Asisten Lab 2027', 'QR-IELA-1411250026', 'https://drive.google.com/file/d/1NYdmj2oLPibPXylur2jjRNWTKhJ2Pyhf/view?usp=drivesdk') ON CONFLICT (pendaftar_id) DO NOTHING;
INSERT INTO pendaftar (pendaftar_id, user_id, nim, nama, nama_panggilan, jenis_kelamin, ttl, alamat_asal, alamat_sekarang, no_hp, hobby, cita_cita, motto_hidup, semester, prodi, ipk, bidang_pilihan_1, bidang_pilihan_2, keterampilan, motivasi, target_iela, riwayat_organisasi, pelatihan_diikuti, buku_diresume, url_foto, url_khs, url_cv, url_sertifikat, url_resume, status_pendaftaran, qr_code_id, url_jurnal_referensi) VALUES ('PDF-9065', 'USR-4399', '1411250060', 'ALVA FIKROH AUVA', 'FIKROH', 'Perempuan', 'Tuban, 10 Juni 2006', 'Ds. Sumurgung, RT 007/ RW 001, Kec. Palang, Kab. Tuban', 'Ds. Sumurgung, RT 007/ RW 001, Kec. Palang, Kab. Tuban', '88996829667.0', 'Cooking', 'Pegawai BUMN', 'Gagal hari ini bukan berarti kalah diesok hari.', '3.0', 'Teknik Industri Unirow', 3.81, '2. Ergonomi', '1. Fisika', 'Ergofellow, Autodesk Inventor', 'Mengembangkan kompetensi akademik dan investasi portofolio', 'Menguasai seluruh prosedur praktikum  tidak hanya disatu bidang', 'OSIS (Organisasi Siswa Intera Sekolah)', 'Pelatihan EXCEL', 'Redesain Troli Pada UMKM Ayam Goreng Keraton Dengan  Menggunakan Metode Antropometri Dan Handtools Design', 'https://drive.google.com/file/d/1n4eMDKCKMJo0uwV-oqUESogBJb1ysnYE/view?usp=drivesdk', 'https://drive.google.com/file/d/1HBtg-sTYT1ZIlch9bCNGoXc2_2nJLeUH/view?usp=drivesdk', 'https://drive.google.com/file/d/1ORM-P7PrZ2CwB06z02szgbnWmDgJBxUX/view?usp=drivesdk', 'https://drive.google.com/file/d/1QNGiRY0fIu-hrJHnn3drAo-q2JZRvSYW/view?usp=drivesdk', 'https://drive.google.com/file/d/1LDwn5Ttf-CIJNnjL82rKR3KpJqEl0vv2/view?usp=drivesdk', 'Lolos Asisten Lab 2027', 'QR-IELA-1411250060', 'https://drive.google.com/file/d/1Id_ON4uHzoVhWqZ2nFcis3n-Ixo3IUqo/view?usp=drivesdk') ON CONFLICT (pendaftar_id) DO NOTHING;
INSERT INTO pendaftar (pendaftar_id, user_id, nim, nama, nama_panggilan, jenis_kelamin, ttl, alamat_asal, alamat_sekarang, no_hp, hobby, cita_cita, motto_hidup, semester, prodi, ipk, bidang_pilihan_1, bidang_pilihan_2, keterampilan, motivasi, target_iela, riwayat_organisasi, pelatihan_diikuti, buku_diresume, url_foto, url_khs, url_cv, url_sertifikat, url_resume, status_pendaftaran, qr_code_id, url_jurnal_referensi) VALUES ('PDF-6845', 'USR-2966', '1411250049', 'Sarah Meilani', 'Sarah', 'Perempuan', 'Tuban, 16 Mei 2007', 'Ds.Sembungrejo, Kec.Merakurak, Kab.Tuban, Jawa Timur', 'Ds.Sembungrejo, Kec.Merakurak, Kab.Tuban, Jawa Timur', '85695088033.0', 'Mendengarkan Musik, Membaca, Travelling.', 'Pengusaha di Bidang Kontruksi', 'Berjalan di sepanjang garis masa depan', '3.0', 'Teknik Industri Unirow', 3.64, '1. Fisika', '4. Manufaktur (c. CNC)', 'Analisis Laboratorium, Viskositas, Densitas, Bandul Sederhana, Microsoft Word, Excel, PowerPoint.', 'Motivasi saya mendaftar sebagai asisten laboratorium adalah untuk memperdalam pemahaman gagasan  melalui aktivitas praktikum, menaikkan keterampilan dalam menjalankan eksperimen, serta memperluas kemampuan komunikasi, kerja sama, dan tanggung jawab. Saya juga ingin memperoleh pengalaman baru yang dapat menopang pengembangan diri dan kemampuan akademik saya.', 'Mengembangkan kompetensi di bidang Teknik Industri, meningkatkan kemampuan analisis dan manajemen, serta membangun pengalaman yang bermanfaat untuk pengembangan diri dan karier di masa depan.', '-', 'Keselamatan dan Kesehatan Kerja (K3), Excel.', 'Uji coba penggunaan Teepol sebagai bahan alternatif pada eksperimen viskositas di Laboratorium Fisika Dasar', 'https://drive.google.com/file/d/1epu6OQlaBiWlOdAbwCGnWdvM2n7xhwbV/view?usp=drivesdk', 'https://drive.google.com/file/d/1CyE-1ZKKpPYuhChxRKmEyovfFizbybym/view?usp=drivesdk', 'https://drive.google.com/file/d/19Vwwp57p9RX2q-qGbfAkDgfg-zM4WHL3/view?usp=drivesdk', 'https://drive.google.com/file/d/1ZX7KOeB83V-wZaFYuiOb5p04-G3IhL