INSERT INTO pendaftar (pendaftar_id, user_id, nim, nama, nama_panggilan, jenis_kelamin, ttl, alamat_asal, alamat_sekarang, no_hp, hobby, cita_cita, motto_hidup, semester, prodi, ipk, bidang_pilihan_1, bidang_pilihan_2, keterampilan, motivasi, target_iela, riwayat_organisasi, pelatihan_diikuti, buku_diresume, url_foto, url_khs, url_cv, url_sertifikat, url_resume, status_pendaftaran, qr_code_id, url_jurnal_referensi) VALUES ('PDF-5036', 'USR-4811', '1411250039', 'MUNTAMAH', 'MUNTAMAH', 'Perempuan', 'Tuban, 13  Oktober 2007', 'Dsn. Karean, Ds. Gesikan, Kec. Grabagan, Kab. Tuban', 'Dsn. Karean, Ds. Gesikan, Kec. Grabagan, Kab. Tuban', '0823-2874-2031', 'Menyanyi & Mendengarkan musik', 'Menjadi profesional di bidang K3 di perusahaan /industri pertambangan & memberikan motivasi /manfaat bagi banyak orang', '(Tidak perlu membuktikan apapun ke siapapun, hidup bukan tentang memenuhi ekspektasi  orang lain ), (ga takut diomongin orang, cuma takut jadi orang yang ga berguna) & (Kegagalan bukan akhir dari segalanya, jadikan kegagalan sebagai pembelajaran dan jadikan motivasi, bukan alasan untuk berhenti)', '3.0', 'Teknik Industri Unirow', 3.80, '2. Ergonomi', '4. Manufaktur (b. 3D Printing)', 'Memahami dasar-dasar ergonomi dan pengukuran waktu baku melalui praktik perakitan bolpoin. Memiliki pengalaman mengikuti praktikum antropometri dan perancangan fasilitas kerja, mampu menggunakan Microsoft Office serta memiliki pengalaman dasar dalam penggunaan  software ergofellow & inventor untuk mendukung kegiatan akademik', 'Saya ingin mendaftar sebagai asisten laboratorium karena ingin memperdalam pemahaman dan menambah pengalaman di bidang Ergonomi. Saya juga ingin mengembangkan kemampuan dalam menerapkan ilmu yang telah dipelajari selama praktikum, sekaligus belajar bertanggung jawab, bekerja sama, dan mengembangkan kemampuan diri melalui kegiatan laboratorium', 'Berusaha menjalankan tanggung jawab sebagai asisten laboratorium dengan baik, meningkatkan kedisiplinan, serta membangun kerja sama yang baik dengan sesama asisten.', 'Belum memiliki pengalaman organisasi', 'Seminar/Pelatihan k3 Awareness Ruang Tertutup, Pelatihan Excel, Seminar Bahasa Inggris, Seminar Persiapan Karir', 'ANALISIS PROSES PEMBUATAN ALAT UNTUK PENGUKURAN DIMENSI TIRE MOTORCYCLE STUDI KASUS DEPARTEMEN LABORATURIUM QA TIRE PERFORMANCE TESTING PLANT A PT. PPP', 'https://drive.google.com/file/d/1CXiLRSVG7iR3CCD1ADBd9UqpiokRXzXc/view?usp=drivesdk', 'https://drive.google.com/file/d/1R7sXUfe8vkCPdM6w8UAdscLC4Gfg4X_r/view?usp=drivesdk', 'https://drive.google.com/file/d/1xNdSsXVt6jWgFzCJXcOAnGAjpRmZNCwr/view?usp=drivesdk', 'https://drive.google.com/file/d/1NT1vLtCVKQWPZ7TaFXBrCTBWmlZ-pqNO/view?usp=drivesdk', 'https://drive.google.com/file/d/1PEG3bhdbipkPI8eRlCTCrs9rFgLKG-Vi/view?usp=drivesdk', 'Lolos Asisten Lab 2027', 'QR-IELA-1411250039', 'https://drive.google.com/file/d/157z87vWIYbEFtKkh_trXyDR-48p6INsD/view?usp=drivesdk') ON CONFLICT (pendaftar_id) DO NOTHING;
INSERT INTO pendaftar (pendaftar_id, user_id, nim, nama, nama_panggilan, jenis_kelamin, ttl, alamat_asal, alamat_sekarang, no_hp, hobby, cita_cita, motto_hidup, semester, prodi, ipk, bidang_pilihan_1, bidang_pilihan_2, keterampilan, motivasi, target_iela, riwayat_organisasi, pelatihan_diikuti, buku_diresume, url_foto, url_khs, url_cv, url_sertifikat, url_resume, status_pendaftaran, qr_code_id, url_jurnal_referensi) VALUES ('PDF-8950', 'USR-5876', '1411250029', 'MAR  ATUS SHOLIHAH', 'ATUS', 'Perempuan', 'Tuban, 05 Januari 2007', 'Ds. Cangkring Rt-007/Rw-002   Kec.Plumpang Kab . Tuban', 'Ds. Cangkring Rt-007/Rw-002   Kec.Plumpang Kab . Tuban', '82132204425.0', 'Memasak  dan membahagiakan orang lainn', 'Sukses Dunia Akhirat', 'Tetap tersenyum  dan selalu menebar kebaikan, walaupun sering tidak dihargai', '3.0', 'Teknik Industri Unirow', 3.96, '2. Ergonomi', '2. Ergonomi', 'Komunikasi dan mengajar, Manajemen waktu dan disiplin serta mampu  mendolah data pada Ms. excel dan menyusun laporan pada Ms. word', 'Ingin memperdalam pemahaman materi, serta mengembangkan soft skil dan memperluas relasi', 'Target saya sederhana: tidak ada praktikan yang pulang dengan cedera, dan tidak ada alat yang ditinggalkan berantakan, dan patuh pada prosedur K3', 'Dewan Penggalang  2020-2022', 'Pelatihan MICROSOFT hack for gen z', 'Analisis Risiko Ergonomi dan Keluhan MSDs pada Aktivitas Lifting to Positioning Instalasi Outdoor AC: Penelitian ini menganalisis risiko ergonomi dan keluhan musculoskeletal disorders (MSDs) pada 10 teknisi AC home service saat memasang unit outdoor. Hasil penilaian menggunakan metode WERA dan kuesioner CMDQ menunjukkan bahwa risiko ergonomi berada pada kategori sedang hingga tinggi—dengan skor tertinggi pada tahap positioning (36–47)—serta keluhan dominan dirasakan pada punggung bawah, bahu, dan leher.', 'https://drive.google.com/file/d/1d3kgFNZx8YoyFm_f0u_SUsNJMDmkjr_q/view?usp=drivesdk', 'https://drive.google.com/file/d/1aDnKrMd48DGTDb8MH1RkI84Gd9gTKn7c/view?usp=drivesdk', 'https://drive.google.com/file/d/13ya6tHvCKUVrxIkkxMIGsnLrFgjVwoQa/view?usp=drivesdk', 'https://drive.google.com/file/d/1iiqXKLrA9YZCPLBU2EscjrQ4gutA8rXS/view?usp=drivesdk', 'https://drive.google.com/file/d/1nHdfTQs6U6_ou7Ke1nqvBrDcvn9pwX4i/view?usp=drivesdk', 'Lolos Asisten Lab 2027', 'QR-IELA-1411250029', 'https://drive.google.com/file/d/16NWlRRsiZ5M-ZP7_pMq2CMmXhY9k_Nid/view?usp=drivesdk') ON CONFLICT (pendaftar_id) DO NOTHING;
