s://drive.google.com/file/d/1PKBJZTZldfi521QMK_8fEoghRSPlr6Y0/view?usp=drivesdk', 'https://drive.google.com/file/d/1Nk_rfwvaq_AGcJQM9whuWB-zMAOYUGrf/view?usp=drivesdk', 'https://drive.google.com/file/d/1lsHIKPCEKDB-y8tSwO0-lVuJFaV-T2hm/view?usp=drivesdk', 'Tidak Lolos', 'QR-IELA-1411250072', 'https://drive.google.com/file/d/1Lw99zGysEy-7lhM3ZlajM1m4ApO52f8t/view?usp=drivesdk') ON CONFLICT (pendaftar_id) DO NOTHING;
