INSERT INTO pendaftar (pendaftar_id, user_id, nim, nama, nama_panggilan, jenis_kelamin, ttl, alamat_asal, alamat_sekarang, no_hp, hobby, cita_cita, motto_hidup, semester, prodi, ipk, bidang_pilihan_1, bidang_pilihan_2, keterampilan, motivasi, target_iela, riwayat_organisasi, pelatihan_diikuti, buku_diresume, url_foto, url_khs, url_cv, url_sertifikat, url_resume, status_pendaftaran, qr_code_id, url_jurnal_referensi) VALUES ('PDF-5032', 'USR-3652', '1411250043', 'NAYAKA BIMA SAKTIKA ZAKY', 'NAYAKA', 'Laki-laki', 'Tuban, 17  April 2007', 'Dsn Grebegan, Ds Kepohagung, rt 01 rw 06, Kecamatan Plumpang, Kabupaten Tuban', 'Dsn Grebegan, Ds Kepohagung, rt 01 rw 06, Kecamatan Plumpang, Kabupaten Tuban', '85649725627.0', 'Bersepeda', 'wirausahawan suksess / pengusaha suksess', '"Inna ma''al ''usri yusra" — Sesungguhnya bersama kesulitan itu ada kemudahan.', '3.0', 'Teknik Industri Unirow', 3.73, '1. Fisika', '1. Fisika', 'pengukuran dan penggunaan alat ukur, perhitungan fisika dasar,  pemahaman dasar praktikum fisika', 'Motivasi saya mendaftar sebagai Asisten Laboratorium Fisika Dasar Industri adalah untuk memperdalam pemahaman fisika dasar, menambah pengalaman berorganisasi, serta mengembangkan kemampuan komunikasi, kedisiplinan, dan tanggung jawab. Saya juga ingin membantu praktikan memahami materi dengan baik sekaligus meningkatkan kemampuan diri sebagai mahasiswa Teknik Industri.', 'Target saya jika diterima menjadi Asisten Laboratorium adalah memahami materi dan prosedur praktikum dengan lebih baik, meningkatkan kemampuan menggunakan alat ukur dan mengolah data hasil percobaan, serta mampu membantu praktikan yang mengalami kesulitan. Saya juga ingin menjalankan setiap tugas dengan disiplin dan tanggung jawab, menjaga alat laboratorium, serta memberikan kontribusi positif agar kegiatan praktikum berjalan dengan tertib dan lancar.', '-', '-', 'Pengaruh Massa dan Jenis Pegas terhadap Konstanta Pegas: Studi Praktikum', 'https://drive.google.com/file/d/1O2W-OgXrUfBaps7TMir4YBMM7E7k10Pq/view?usp=drivesdk', 'https://drive.google.com/file/d/1hl5w5SsknQ57QWBNVv29ifi72UTqNA8f/view?usp=drivesdk', 'https://drive.google.com/file/d/1djfI6R23DiiLLwhKkaoqOE37jAYkOVkw/view?usp=drivesdk', '#', 'https://drive.google.com/file/d/1dFtYMx1F6WXD3yh2MKZMsCXXqnY10-NC/view?usp=drivesdk', 'Lolos Asisten Lab 2027', 'QR-IELA-1411250043', 'https://drive.google.com/file/d/1Z5RdJfccLl91rxeAj7T_zPrIitQlsWLW/view?usp=drivesdk') ON CONFLICT (pendaftar_id) DO NOTHING;
INSERT INTO pendaftar (pendaftar_id, user_id, nim, nama, nama_panggilan, jenis_kelamin, ttl, alamat_asal, alamat_sekarang, no_hp, hobby, cita_cita, motto_hidup, semester, prodi, ipk, bidang_pilihan_1, bidang_pilihan_2, keterampilan, motivasi, target_iela, riwayat_organisasi, pelatihan_diikuti, buku_diresume, url_foto, url_khs, url_cv, url_sertifikat, url_resume, status_pendaftaran, qr_code_id, url_jurnal_referensi) VALUES ('PDF-4118', 'USR-7783', '1411250085', 'WAFIQUL IRSYAD', 'WAFIQUL', 'Laki-laki', 'Tuban, 01 Jan 2005', '-', '-', '-', '-', '-', '-', '3.0', 'Teknik Industri Unirow', 3, '1. Fisika', '2. Ergonomi', '-', '-', '-', '-', '-', '-', '#', '#', '#', '#', '#', 'Tidak Lolos', 'QR-IELA-1411250085', '#') ON CONFLICT (pendaftar_id) DO NOTHING;
INSERT INTO pendaftar (pendaftar_id, user_id, nim, nama, nama_panggilan, jenis_kelamin, ttl, alamat_asal, alamat_sekarang, no_hp, hobby, cita_cita, motto_hidup, semester, prodi, ipk, bidang_pilihan_1, bidang_pilihan_2, keterampilan, motivasi, target_iela, riwayat_organisasi, pelatihan_diikuti, buku_diresume, url_foto, url_khs, url_cv, url_sertifikat, url_resume, status_pendaftaran, qr_code_id, url_jurnal_referensi) VALUES ('PDF-5423', 'USR-8831', '1411250063', 'Arsa Raditya Argyansyah', 'Argy', 'Laki-laki', 'Tuban, 07 juli 2007', 'Sumurgung,montong, Tuban', 'Sumurgung montong Tuban', '83135361376.0', 'Hobi bermain game online', 'pebisnis', 'tenang di awal, teliti di tengah, puas di ahir', '3.0', 'Teknik Industri Unirow', 3.45, '4. Manufaktur (a. Bubut)', '3. Statistika', 'Memiliki kompetensi dasar yang kuat pada proses manufaktur, khususnya pengoperasian mesin bubut serta penggunaan alat ukur presisi seperti jangka sorong. Mampu membaca dan menerapkan gambar teknik. Di bidang statistika industri, terampil mengolah dan menganalisis data menggunakan Microsoft Excel, Minitab, dan SPSS (uji normalitas, homogenitas, regresi, korelasi, ANOVA). Menguasai software pendukung lainnya seperti Microsoft Office (Word, PowerPoint), Python, dan Inventor', 'Saya memiliki minat besar untuk mendalami dan mengamalkan ilmu yang telah saya pelajari di bangku kuliah,khususnya di bidang proses manufaktur dan statistika industri. Bergabung sebagai asisten laboratorium IELA merupakan kesempatan ideal bagi saya untuk berkontribusi dalam membantu persiapan praktikum, pendampingan praktikan, perawatan alat, serta pengolahan data dan penyusunan laporan laboratorium. Saya melihat peran asisten bukan hanya sebagai pengajar, tetapi juga sebagai jembatan antara teori dan praktik. Dengan kedisiplinan, ketelitian, dan kemampuan komunikasi yang saya miliki, saya siap membantu menciptakan suasana praktikum yang kondusif, aman, dan efektif bagi seluruh praktikan', 'saya ingin menguasai seluruh SOP laboratorium, khususnya Lab manufaktur dan lab komputer statistika, serta menjadi asisten yang andal dalam mendampingi praktikan, menjaga penerapan K3, dan membantu mahasiswa memahami materi praktikum secara aplikatif, berkontribusi pada peningkatan kualitas modul dan fasilitas laboratorium melalui pemanfaatan kemampuan analisis data, sekaligus mengembangkan soft skill kepemimpinan dan manajemen waktu agar dapat menjadi bagian dari tim yang solid dalam memajukan Laboratorium Teknik Industri UNIROW', 'menjadi bendahara pengurus komisariat (PK) di sekolahan masa jabatan 2023-2025, menjabat sebagai sekertaris PAC montong 2025-sekarang', 'Pelatihan Excel, seminar persiapan karir', 'Studi Eksperimen Kecepatan Putar Spindle Dan Kedalaman Potong Terhadap Getaran Pahat Dan Tingkat Kekasaran Pada Proses Pembuatan Poros Menggunakan Mesin Bubut. Pembelajaran statistik berbasis statistical product and service solutions (SPSS) untuk meningkatkan hasil belajar mahasiswa teknik industri', 'https://drive.google.com/file/d/1NAMvmTyGjJfJ8zEBK2tjWiMnj_Xl8De_/view?usp=drivesdk', 'https://drive.google.com/file/d/1S6vJx2x61ZOnLJF3ao1Orm3WUDbi2E79/view?usp=drivesdk', 'https://drive.google.com/file/d/1XqQ7C7CUA9S3uWgEdtKLc6mXT48E2--Q/view?usp=drivesdk', 'https://drive.google.com/file/d/1m8AYNGWMV32wUBk7DaZo52LDfuNQgt3C/view?usp=drivesdk', 'https://drive.google.com/file/d/188CG3Cs-lhNKZPVtzIS7X7nldAlO5zL4/view?usp=drivesdk', 'Lolos Asisten Lab 2027', 'QR-IELA-1411250063', 'https://drive.google.com/file/d/1SVwt8V-qKw2o2skhJaFD2fROev9AtaFL/view?usp=drivesdk') ON CONFLICT (pendaftar_id) DO NOTHING;
