INSERT INTO pendaftar (pendaftar_id, user_id, nim, nama, nama_panggilan, jenis_kelamin, ttl, alamat_asal, alamat_sekarang, no_hp, hobby, cita_cita, motto_hidup, semester, prodi, ipk, bidang_pilihan_1, bidang_pilihan_2, keterampilan, motivasi, target_iela, riwayat_organisasi, pelatihan_diikuti, buku_diresume, url_foto, url_khs, url_cv, url_sertifikat, url_resume, status_pendaftaran, qr_code_id, url_jurnal_referensi) VALUES ('PDF-5299', 'USR-8396', '1411250086', 'WINDI MILA LESTARI', 'WINDI', 'Perempuan', 'Tuban, 02 Maret 2007', 'Ds.Remen Kec.Jenu Kab.Tuban', 'Ds.Remen Kec.Jenu Kab.Tuban', '82143969635.0', 'Bermain game roblox', 'Perwira Petamina', 'Pokoknya hiduplah sehidup hidupnya', '3.0', 'Teknik Industri Unirow', 3.63, '1. Fisika', '1. Fisika', 'Saya memahami dasar-dasar fisika terapan dan terbiasa melakukan pengamatan serta pencatatan data secara teliti. Saat SMK, saya pernah melakukan penelitian pertumbuhan tanaman pakcoy dengan membandingkan air rendaman beras dan air biasa .Dari situ saya belajar menyusun langkah penelitian, mengamati, mencatat data, dan menarik kesimpulan. Saya juga mampu mengolah data sederhana dengan Excel dan menyusun laporan. Saya terbiasa disiplin, teliti, dan bekerja dalam tim.', 'Saya ingin menjadi aslab untuk belajar dari pengalaman nyata di laboratorium, bukan hanya teori. Saya ingin melatih tanggung jawab dan kedisiplinan, serta membantu mahasiswa memahami praktikum dengan lebih mudah.', 'Saya ingin menguasai modul dan alat praktikum dengan cepat, bisa dipercaya jadi asisten pendamping, serta ikut menjaga dan mengembangkan laboratorium.', '-', 'Pelatihan Excel', 'Analisis pengaruh suhu terhadap warna, Densitas, dan  Viskositas madu hutan lebah Apis Dorsata dari  kecamatan Lunyuk-Sumbawa', 'https://drive.google.com/file/d/1poX7dl4h_-0D9ZbjhNXYLILSfvlwYN2r/view?usp=drivesdk', 'https://drive.google.com/file/d/1vUcESSRec94HzaG3jNwAUxZEvG4fiMU4/view?usp=drivesdk', 'https://drive.google.com/file/d/1In-M3oa7oaT9pHOPmuX6_KAKZKQwegwu/view?usp=drivesdk', 'https://drive.google.com/file/d/1B3rDaalXxfMMZZ0AznXjzQvlsd0Wb7wK/view?usp=drivesdk', 'https://drive.google.com/file/d/1ttjRt0eWh-w2vPOF_7WrieX3ei4ZvQq0/view?usp=drivesdk', 'Tidak Lolos', 'QR-IELA-1411250086', 'https://drive.google.com/file/d/1ZwCUZbzY71GHjQDnLZ5TfGVFrcj_aWH9/view?usp=drivesdk') ON CONFLICT (pendaftar_id) DO NOTHING;
