INSERT INTO pendaftar (pendaftar_id, user_id, nim, nama, nama_panggilan, jenis_kelamin, ttl, alamat_asal, alamat_sekarang, no_hp, hobby, cita_cita, motto_hidup, semester, prodi, ipk, bidang_pilihan_1, bidang_pilihan_2, keterampilan, motivasi, target_iela, riwayat_organisasi, pelatihan_diikuti, buku_diresume, url_foto, url_khs, url_cv, url_sertifikat, url_resume, status_pendaftaran, qr_code_id, url_jurnal_referensi) VALUES ('PDF-7781', 'USR-6720', '1411250074', 'M. DOHAN ALVIANSYAH', 'Dohan', 'Laki-laki', 'Lamongan, 11 Mei 2007', '-Lamongan brondong', '-Lamongan brondong', '-85746515967.0', 'Belajar', '-Welder', '-coba aja dulu kalau gagal coba lagi', '3.0', 'Teknik Industri Unirow', 3.33, '4. Manufaktur (c. CNC)', '4. Manufaktur (c. CNC)', '-Welding dan lain lain', '-Saya ingin menjadi asisten laboratorium untuk menambah pengalaman, memperdalam ilmu yang saya pelajari, dan mengembangkan kemampuan diri. Selain itu, saya juga ingin belajar bekerja sama, melatih tanggung jawab, serta berbagi ilmu dengan mahasiswa lain.', '-Target saya adalah meningkatkan pengetahuan dan keterampilan, mendapatkan pengalaman baru, serta menjadi asisten laboratorium yang disiplin, bertanggung jawab, dan mampu membantu mahasiswa lain dalam kegiatan praktikum.', '-belum pernah', '-Indonesia Stock Exchange,', '-penerapan teknologi computer numerical control (CNC) dalam proses machining untuk meningkatkan presisi dan efisiensi', 'https://drive.google.com/file/d/1gvQx6Odf3vaCZCC89Hl_WPnhi0wbfl3l/view?usp=drivesdk', 'https://drive.google.com/file/d/1d-QHyJnyBpwfK8bHbYahV0ZGZH6g0fD0/view?usp=drivesdk', 'https://drive.google.com/file/d/16LWRt6llcl-erP9VGi5pzjLSV_lFVgnZ/view?usp=drivesdk', 'https://drive.google.com/file/d/13u0BrQY0Zs4UTqImwA35ZKB0pxYc2wMt/view?usp=drivesdk', 'https://drive.google.com/file/d/1ccZnDO6oW6qj9XADqdyMlPj9xkH1ZY30/view?usp=drivesdk', 'Tidak Lolos', 'QR-IELA-1411250074', 'https://drive.google.com/file/d/1EpLHB3eopjSnZHLFPhdinTu7-WuHV2my/view?usp=drivesdk') ON CONFLICT (pendaftar_id) DO NOTHING;
INSERT INTO pendaftar (pendaftar_id, user_id, nim, nama, nama_panggilan, jenis_kelamin, ttl, alamat_asal, alamat_sekarang, no_hp, hobby, cita_cita, motto_hidup, semester, prodi, ipk, bidang_pilihan_1, bidang_pilihan_2, keterampilan, motivasi, target_iela, riwayat_organisasi, pelatihan_diikuti, buku_diresume, url_foto, url_khs, url_cv, url_sertifikat, url_resume, status_pendaftaran, qr_code_id, url_jurnal_referensi) VALUES ('PDF-4818', 'USR-8089', '1411250069', 'Fitria Atiqotul Farida', 'Farida', 'Perempuan', 'Tuban, 26 Oktober 2006', 'Desa Kaliuntu - Kec. Jenu - Kab. Tuban', 'Desa Kaliuntu - Kec. Jenu - Kab. Tuban', '85746501533.0', 'jogging', 'Human Resources Development (HRD) di Perusahaan Industri', '"jika merasa gagal dalam mencapai sebuah mimpi, jangan khawatir mimpi-mimpi lain bisa diciptakan"', '3.0', 'Teknik Industri Unirow', 3.84, '4. Manufaktur (b. 3D Printing)', '4. Manufaktur (b. 3D Printing)', '1. Microsoft Word dan Excel 2. Basic IBM SPSS Statistics 3. Basic Minitab 4. Basic Autodesk Inventor 5. Editing Video', 'Motivasi saya ingin bergabung sebagai Asisten Laboratorium ialah saya ingin memperdalam pemahaman materi perkuliahan, meningkatkan kemampuan komunikasi dan kerja sama tim, serta memperoleh pengalaman dalam membantu pelaksanaan kegiatan praktikum. Selain itu, saya berharap dapat meningkatkan kedisiplinan, tanggung jawab, dan kemampuan dalam menyelesaikan masalah.', 'Meningkatkan kemampuan diri, baik dalam bidang akademik maupun keterampilan praktis, dan memberikan kontribusi positif bagi laboratorium dan mahasiswa lainnya', '-', '1. Pelatihan Microsoft Excel HMTI-IEC Unirow 2026 2. Seminar Persiapan Karir HMTI-IEC Unirow 2026', 'Optimasi Parameter Proses 3D Printing dengan Metode Taguchi', 'https://drive.google.com/file/d/1dMrqLSngZk4nZROWYa0Bo_0Uotm1GheW/view?usp=drivesdk', 'https://drive.google.com/file/d/1iKqhjp8rCPM9VKgrFXkwcEXwUlfEAuoM/view?usp=drivesdk', 'https://drive.google.com/file/d/1fKIMyb9PYW5RAWzOYRy5acgfD3TXisKz/view?usp=drivesdk', 'https://drive.google.com/file/d/1Gyrmz5TjOr9eLJlFNkJS7kAuB-CMjPWb/view?usp=drivesdk', 'https://drive.google.com/file/d/1qS7_vE_cvrWkzzc76OeboYenyOFgb1R8/view?usp=drivesdk', 'Tidak Lolos', 'QR-IELA-1411250069', 'https://drive.google.com/file/d/1QHgLcareMJ-VT9UnQeSO1CnxZHuOU_qZ/view?usp=drivesdk') ON CONFLICT (pendaftar_id) DO NOTHING;
